import SwiftUI

/// Vector artwork shared with Android Material Outlined. Generated by tools/prepare_ui_assets.py.
struct OmniIcon: View {
    let name: String
    var size: CGFloat = 24
    private static let assets: [String:String] = [
        "arrow.down.to.line": "material_download",
        "arrow.left": "material_arrow_back",
        "arrow.up.right.square": "material_open_in_new",
        "bolt.fill": "material_bolt",
        "checkmark": "material_check",
        "chevron.down": "material_expand_more",
        "chevron.right": "material_chevron_right",
        "chevron.up": "material_expand_less",
        "doc.on.clipboard": "material_content_paste",
        "folder": "material_folder",
        "gearshape": "material_settings",
        "gif": "material_gif",
        "globe": "material_public",
        "house": "material_home",
        "icloud.and.arrow.down": "material_cloud_download",
        "info.circle": "material_info",
        "link": "material_link",
        "music.note": "material_audiotrack",
        "paintpalette": "material_palette",
        "person.crop.circle": "material_account_circle",
        "photo.on.rectangle": "material_photo_library",
        "plus": "material_add",
        "server.rack": "material_storage",
        "speaker.slash": "material_volume_off",
        "trash": "material_delete",
        "video": "material_videocam",
        "xmark": "material_close",
        "xmark.circle.fill": "material_close",
    ]
    var body: some View {
        Group {
            if let asset = Self.assets[name] { Image(asset).renderingMode(.template).resizable().scaledToFit() }
            else { Image(systemName: name).resizable().scaledToFit() }
        }.frame(width: size, height: size).accessibilityHidden(true)
    }
}
